          tokens: intl.formatMessage({ id: "chat.goalCommand.summaryTokens" }),
          commands: intl.formatMessage({ id: "chat.goalCommand.summaryCommands" }),
          statusLabel: intl.formatMessage({ id: `chat.goalStatus.${currentGoal.status}` }),
        }),
      );
      return;
    }

