                  q.id,
                  {
                    answers: [
                      (q.options as Array<Record<string, string>>)[0].label,
                    ],
                  },
                ]),
              );
              resolveApproval(reqId, { answers }).catch((err) =>
                console.error("Auto-approve user input failed:", err),
